// NewApp - Generated by app subagent
import React from 'react';

const TABLE = 'new_app';

export default function NewApp({ appConfig }: { appConfig?: any }) {
  const db = (window as any).__workspaceDb;
  const { data: items, loading, refresh } = (window as any).useWorkspaceDB(TABLE, {
    orderBy: { column: 'created_at', direction: 'desc' },
    limit: 100,
  });

  if (loading) return <div className="p-4 text-center">Loading...</div>;

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold mb-4">NewApp</h1>
      <p className="text-gray-500">Setting up your app...</p>
    </div>
  );
}
